#!/bin/sh
# usage: runlist.sh OUTDIR  (run from a tests/ directory)
OUT="$1"; mkdir -p "$OUT"
for t in check_pf_pr_rpe_pipeline check_pr_r_dependent_n check_h4_df10_rpe_batch check_h6_price_pipeline_coverage check_r_variable_compiled_price check_h4_price_pipeline_integration check_h4_df10_price_provider check_h6_df19_price_provider check_pr_rpe_rmse check_pr_rpe_rmse_integration check_rpe_provider_integration check_h4_s0_v2_intake check_candidate_id_cache check_pr_resource_wiring check_rpe_r_price_intake check_rpe_s3_intake check_rpe_new_evidence_intake check_abc_d_v2_integration check_rpe_signal_statistics_caller check_bv2_mean_price check_rpe_decoder_statistics check_rpe_shot_evaluation_design check_pr_rpe_rmse_evidence check_full_baseline_v2_requests check_rpe_deterministic_refinement check_rpe_deterministic_risk check_pr_rpe_rmse_controller check_rpe_shot_allocation check_rpe_price_implementation_guard check_pr_rpe_method_coverage check_rpe_risk_intervals; do [ -f $t.py ] && echo $t; done | xargs -P 32 -I{} sh -c 's=$(date +%s.%N); timeout 1500 /home/AbeHiromu/projects/h6-environments/20261011/venv/bin/python -B {}.py > "'"$OUT"'"/{}.log 2>&1; rc=$?; e=$(date +%s.%N); n=$(grep -E "^Ran [0-9]+ test" "'"$OUT"'"/{}.log | awk "{print \$2}"); echo "{} $rc ${n:-0} $(echo "$e - $s" | bc)" >> "'"$OUT"'"/rc.txt'
sort "$OUT/rc.txt" > "$OUT/rc.sorted.txt"
awk '{n++; t+=$3; if($2!=0) f=f" "$1} END {print "files="n" tests="t" failed:"f}' "$OUT/rc.sorted.txt"
